// ASCII source only: intended inert Persian, 2/3/4-byte scalars and text edge cases.
// Numeric truths are independent expectations, not computed from the string under test.
import assert from 'node:assert/strict';
export const UNICODE_TEXT='\u0645\u062a\u0646 \u0622\u0632\u0645\u0627\u06cc\u0634\u06cc \u00a2 \u20ac \u{1f9ea} e\u0301 \ufffd \ufeff';
export const UNICODE_POINTS=[0x0645,0x062a,0x0646,0x20,0x0622,0x0632,0x0645,0x0627,0x06cc,0x0634,0x06cc,0x20,0x00a2,0x20,0x20ac,0x20,0x1f9ea,0x20,0x65,0x0301,0x20,0xfffd,0x20,0xfeff];
export const UNICODE_UTF8=Buffer.from([0xd9,0x85,0xd8,0xaa,0xd9,0x86,0x20,0xd8,0xa2,0xd8,0xb2,0xd9,0x85,0xd8,0xa7,0xdb,0x8c,0xd8,0xb4,0xdb,0x8c,0x20,0xc2,0xa2,0x20,0xe2,0x82,0xac,0x20,0xf0,0x9f,0xa7,0xaa,0x20,0x65,0xcc,0x81,0x20,0xef,0xbf,0xbd,0x20,0xef,0xbb,0xbf]);
export function assertUnicode(value){assert.deepEqual(Array.from(value,c=>c.codePointAt(0)),UNICODE_POINTS);assert.deepEqual(Buffer.from(value,'utf8'),UNICODE_UTF8);}
